import {
  MainWrapper,
  ContentWrapper,
  ProjectModule,
  Image,
  ProjectContentWrapper,
  Button
} from "./index.stitches";
import data from "../../data/project.json";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faArrowRight} from '@fortawesome/free-solid-svg-icons'

function ProjectGrid() {
  return (
    <MainWrapper>
      <ContentWrapper>
        {data.map((item, i) => {
          return (
            <ProjectModule key={i}>
              <Image />
              <ProjectContentWrapper>
                <p>{i}/{data.length}</p>
                <p>{item[0]}</p>
                <Button href={''}>
                    <p>Link to story</p>
                    <FontAwesomeIcon icon={faArrowRight}/>
                    </Button>
                <p><span>{item[2]}</span>{item[3]}</p>
              </ProjectContentWrapper>
            </ProjectModule>
          );
        })}
      </ContentWrapper>
    </MainWrapper>
  );
}

export default ProjectGrid;
